import React, { useState } from 'react';
import axios from 'axios';
import './Login.css'; // ඔයාගේ පරණ CSS ෆයිල් එක මෙතනට link කරන්න

const Login = ({ setShowLoginModal, handleLoginSubmit }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const handleFormSubmit = (e) => {
        e.preventDefault();
        handleLoginSubmit(username, password);
    };

    return (
        // මේ classNames ඔයාගේ Login.css එකේ තියෙනවා ඇති
        <div className="login-overlay">
            <div className="login-modal">
                <h2>Welcome to Aura Pen</h2>
                <form onSubmit={handleFormSubmit}>
                    <div className="input-group">
                        <input type="text" placeholder="Student ID" onChange={(e) => setUsername(e.target.value)} required />
                    </div>
                    <div className="input-group">
                        <input type="password" placeholder="Password" onChange={(e) => setPassword(e.target.value)} required />
                    </div>
                    <button type="submit" className="login-btn">Login</button>
                    <button type="button" onClick={() => setShowLoginModal(false)} className="cancel-btn">Cancel</button>
                </form>
            </div>
        </div>
    );
};

export default Login;
